// function canApply(age, income, isStudent)
// Student aur <30: "Student discount"
// Income < 300000: "Low income benefit"
// Age > 60: "Senior citizen benefit"
// Baaki: "No special benefit"

solution:
function canApply(age, income, isStudent) {
  if (isStudent && age < 30) return "Student discount"
  if (income < 300000) return "Low income benefit"
  if (age > 60) return "Senior citizen benefit"
  return "No special benefit"
}
